'use strict';

// MODULES //

var constantFunction = require( '@stdlib/utils-constant-function' );
var isnan = require( '@stdlib/math-base-assert-is-nan' );
var sqrt = require( '@stdlib/math-base-special-sqrt' );
var exp = require( '@stdlib/math-base-special-exp' );


// MAIN //

/**
* Returns a function for evaluating the moment-generating function (MGF) of a Wald distribution with mean `mu` and shape parameter `lambda`.
*
* @param {PositiveNumber} mu - mean
* @param {PositiveNumber} lambda - shape parameter
* @returns {Function} MGF
*
* @example
* var mgf = factory( 2.0, 3.0 );
*
* var y = mgf( 0.1 );
* // returns ~1.2405
*
* y = mgf( 0.2 );
* // returns ~1.6085
*/
function factory( mu, lambda ) {
	var mu2Lambda;
	var lambdaMu;
	var tmax;
	if (
		isnan( mu ) ||
		isnan( lambda ) ||
		mu <= 0.0 ||
		lambda <= 0.0
	) {
		return constantFunction( NaN );
	}
	lambdaMu = lambda / mu;
	mu2Lambda = 2.0 * mu * mu / lambda;
	tmax = lambda / ( 2.0 * mu * mu );
	return mgf;

	/**
	* Evaluates the moment-generating function (MGF) for a Wald distribution.
	*
	* @private
	* @param {number} t - input value
	* @returns {number} evaluated MGF
	*
	* @example
	* var y = mgf( 0.1 );
	* // returns <number>
	*/
	function mgf( t ) {
		if (
			isnan( t ) ||
			t > tmax
		) {
			return NaN;
		}
		return exp( lambdaMu * ( 1.0 - sqrt( 1.0 - ( mu2Lambda * t ) ) ) );
	}
}


// EXPORTS //

module.exports = factory;
